278		}
279		switch typed := value.(type) {
280		case float64:
281			if typed >= 1 && typed <= float64(math.MaxInt) && math.Trunc(typed) == typed {
282				return int(typed), nil
283			}
284		case int:
285			if typed >= 1 {
