292	func readMCPMessage(reader *bufio.Reader) (mcpMessage, mcpFrameMode, error) {
293		length := -1
294		for {
295			line, err := reader.ReadString('\n')
296			if err != nil {
297				return mcpMessage{}, "", err
298			}
299			line = strings.TrimRight(line, "\r\n")
300			if strings.HasPrefix(strings.TrimSpace(line), "{") {
301				var msg mcpMessage
302				if err := json.Unmarshal([]byte(strings.TrimSpace(line)), &msg); err != nil {
303					return mcpMessage{}, "", err
304				}
305				return msg, mcpFrameJSONLine, nil
306			}
307			if line == "" {
308				break
309			}
310			name, value, ok := strings.Cut(line, ":")
311			if ok && strings.EqualFold(strings.TrimSpace(name), "Content-Length") {
312				parsed, err := strconv.Atoi(strings.TrimSpace(value))
313				if err != nil {
314					return mcpMessage{}, "", err
315				}
316				if parsed < 0 {
317					return mcpMessage{}, "", errors.New("Content-Length must be non-negative")
318				}
319				length = parsed
320			}
321		}
322		if length < 0 {
323			return mcpMessage{}, "", errors.New("missing Content-Length")
324		}
325		if length > maxMCPFrameBytes {
326			return mcpMessage{}, "", fmt.Errorf("Content-Length exceeds maximum frame size of %d bytes", maxMCPFrameBytes)
327		}
328		data := make([]byte, length)
329		if _, err := io.ReadFull(reader, data); err != nil {
330			return mcpMessage{}, "", err
331		}
332		var msg mcpMessage
333		if err := json.Unmarshal(data, &msg); err != nil {
334			return mcpMessage{}, "", err
335		}
336		return msg, mcpFrameContentLength, nil
337	}
338	
339	func writeMCPMessage(out io.Writer, msg mcpMessage, frameMode mcpFrameMode) error {
340		data, err := json.Marshal(msg)
341		if err != nil {
342			return err
343		}
344		if frameMode == mcpFrameJSONLine {
345			_, err = fmt.Fprintf(out, "%s\n", data)
346			return err
347		}
348		_, err = fmt.Fprintf(out, "Content-Length: %d\r\n\r\n%s", len(data), data)
349		return err
350	}
